-- Lane A figures for ap_chemistry: generated by build_load_sql.py, do not hand-edit.
-- 1 figures across 1 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: energy_profile

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('chem-reaction-coordinate', 'ap_chemistry', 'energy_profile', 'The reaction coordinate', 'Reaction coordinate', 'The axis along which a reaction from reactants to products is plotted', 'The axis along which a reaction from reactants to products is plotted', 'Energy plotted against the reaction coordinate. The curve starts at the reactant level on the left, rises to a maximum and then falls to a product level below the reactants on the right, so this example is exothermic. The horizontal axis is the reaction coordinate, the path of the motions that turn reactants into products. Illustrative data.', 'reaction coordinate', 'energy', null, true, null, '["Horizontal axis (reaction coordinate)", "Vertical axis (energy)", "Reaction pathway from reactants to products"]'::jsonb, '{"nodes": [{"e": 40, "label": "reactants", "kind": "level"}, {"e": 120, "label": "", "kind": "ts"}, {"e": 15, "label": "products", "kind": "level"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=chem-next1-figures-2026-10-15', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'chem-reaction-coordinate', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_chemistry' and e.kind = 'vocabulary'
   and e.title = 'Reaction coordinate' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('chem-reaction-coordinate') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('chem-reaction-coordinate');
  if v_n <> 1 then
    raise exception 'expected 1 figures, found %', v_n;
  end if;
end $$;

commit;
